# Strategy Pattern using functions (Pythonic)
def priority_sort(items): return sorted(items, key=lambda x: x.get('priority', 0), reverse=True)
def alpha_sort(items): return sorted(items, key=lambda x: x.get('name', ''))

class TaskManager:
    def __init__(self, sort_strategy=priority_sort):
        self._sort = sort_strategy
        self.tasks = []
    def add(self, task): self.tasks.append(task)
    def set_sort(self, strategy): self._sort = strategy
    def list_tasks(self): return self._sort(self.tasks)

tm = TaskManager()
tm.add({"name": "Fix bug", "priority": 3})
