import java.util.*;
import java.util.stream.*;

record Employee(String name, String department, double salary) {}

public class ModernJava {
    public static void main(String[] args) {
        var employees = List.of(
            new Employee("Alice", "Engineering", 95000),
            new Employee("Bob", "Marketing", 72000),
            new Employee("Charlie", "Engineering", 105000),
            new Employee("Diana", "Marketing", 88000)
        );

        // Group by department and find top earner
        var topByDept = employees.stream()
            .collect(Collectors.groupingBy(
                Employee::department,
                Collectors.maxBy(Comparator.comparingDouble(Employee::salary))
            ));
        topByDept.forEach((dept, emp) ->
            emp.ifPresent(e -> System.out.printf("%s: %s ($%.0f)%n", dept, e.name(), e.salary()))
        );

        // Parallel processing
        double totalSalary = employees.parallelStream()
            .mapToDouble(Employee::salary)
            .sum();
        System.out.printf("Total: $%.0f%n", totalSalary);
    }
}

