class _TodoListPageState extends State<TodoListPage> {
  List<Map<String, dynamic>> todos = [];
  bool loading = true;

  @override
  void initState() {
    super.initState();
    _fetchTodos();
  }

  Future<void> _fetchTodos() async {
    final response = await http.get(Uri.parse('https://api.example.com/todos'));
    setState(() {
      todos = List<Map<String, dynamic>>.from(json.decode(response.body));
      loading = false;
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text('My Todos')),
      body: loading
          ? Center(child: CircularProgressIndicator())
          : ListView.builder(
              itemCount: todos.length,
              itemBuilder: (context, index) {
                final todo = todos[index];
                return ListTile(
                  leading: Icon(
                    todo['done'] ? Icons.check_circle : Icons.circle,
                    color: todo['done'] ? Colors.green : Colors.grey,
                  ),
                  title: Text(todo['title']),
                  subtitle: Text(todo['description'] ?? ''),
                );
              },
            ),
    );
  }
}

# Binary Search Tree
class Node:
    def __init__(self, val):
        self.val = val
        self.left = self.right = None

class BST:
    def __init__(self):
        self.root = None

    def insert(self, val):
        self.root = self._insert(self.root, val)

    def _insert(self, node, val):
        if not node:
            return Node(val)
        if val < node.val:
            node.left = self._insert(node.left, val)
        elif val > node.val:
            node.right = self._insert(node.right, val)
        return node

    def search(self, val):
        return self._search(self.root, val)

    def _search(self, node, val):
        if not node or node.val == val:
            return node
        if val < node.val:
            return self._search(node.left, val)
        return self._search(node.right, val)

    def inorder(self):
        result = []
        def traverse(node):
            if node:
                traverse(node.left)
                result.append(node.val)
                traverse(node.right)
        traverse(self.root)
        return result

tree = BST()
for v in [5, 3, 7, 1, 4, 6, 8]:
